-- ----------------------------
-- Table structure for user
-- ----------------------------
DROP TABLE IF EXISTS `user`;
CREATE TABLE `user` (
  `UID` int(11) NOT NULL AUTO_INCREMENT COMMENT '唯一自增ID',
  `USER_ID` varchar(40) NOT NULL COMMENT '用户名',
  `USER_NAME` varchar(60) NOT NULL DEFAULT '' COMMENT '用户真实姓名',
  `USER_NAME_INDEX` varchar(60) NOT NULL DEFAULT '' COMMENT '用户姓名索引',
  `BYNAME` varchar(20) NOT NULL DEFAULT '' COMMENT '别名',
  `USEING_KEY` char(1) NOT NULL DEFAULT '0' COMMENT '使用USB KEY登录',
  `USING_FINGER` char(1) NOT NULL DEFAULT '0' COMMENT '使用指纹验证',
  `PASSWORD` varchar(50) NOT NULL DEFAULT '' COMMENT '用户密码',
  `KEY_SN` varchar(20) NOT NULL DEFAULT '' COMMENT '绑定USB Key序列号',
  `SECURE_KEY_SN` varchar(20) NOT NULL COMMENT '动态密码卡号',
  `USER_PRIV` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '角色编号',
  `USER_PRIV_NO` smallint(5) unsigned NOT NULL DEFAULT '0' COMMENT '角色排序号',
  `USER_PRIV_NAME` varchar(40) NOT NULL DEFAULT '' COMMENT '角色名称',
  `POST_PRIV` char(1) NOT NULL DEFAULT '0' COMMENT '管理范围',
  `POST_DEPT` varchar(1000) NOT NULL DEFAULT '' COMMENT '管理范围指定部门',
  `DEPT_ID` int(11) NOT NULL DEFAULT '0' COMMENT '部门ID',
  `DEPT_ID_OTHER` varchar(100) NOT NULL DEFAULT '' COMMENT '辅助部门',
  `SEX` char(1) NOT NULL DEFAULT '' COMMENT '性别',
  `BIRTHDAY` date NOT NULL DEFAULT '0000-00-00' COMMENT '生日',
  `IS_LUNAR` char(1) NOT NULL DEFAULT '0' COMMENT '是否农历(1-是,0-否)',
  `TEL_NO_DEPT` varchar(50) NOT NULL DEFAULT '' COMMENT '工作电话',
  `FAX_NO_DEPT` varchar(50) NOT NULL DEFAULT '' COMMENT '工作传真',
  `ADD_HOME` varchar(200) NOT NULL DEFAULT '' COMMENT '家庭住址',
  `POST_NO_HOME` varchar(50) NOT NULL DEFAULT '' COMMENT '家庭邮编',
  `TEL_NO_HOME` varchar(50) NOT NULL DEFAULT '' COMMENT '家庭电话',
  `MOBIL_NO` varchar(50) NOT NULL DEFAULT '' COMMENT '手机号',
  `BP_NO` varchar(50) NOT NULL DEFAULT '' COMMENT 'BP机号',
  `EMAIL` varchar(50) NOT NULL DEFAULT '' COMMENT '电子邮件地址',
  `OICQ_NO` varchar(50) NOT NULL DEFAULT '' COMMENT 'QQ号码',
  `ICQ_NO` varchar(50) NOT NULL DEFAULT '' COMMENT 'ICQ号码',
  `MSN` varchar(200) NOT NULL DEFAULT '' COMMENT 'MSN号码',
  `AVATAR` varchar(20) NOT NULL DEFAULT '' COMMENT '自定义小头像',
  `CALL_SOUND` char(1) NOT NULL DEFAULT '1' COMMENT '短信提示音',
  `LAST_VISIT_TIME` datetime NOT NULL DEFAULT '0000-00-00 00:00:00' COMMENT '上次访问系统的时间',
  `SMS_ON` char(1) NOT NULL DEFAULT '' COMMENT '短信提醒窗口弹出方式(1-自动,0-手动)',
  `MENU_TYPE` char(1) NOT NULL DEFAULT '1' COMMENT '登录模式(1-在本窗口打开OA,2-在新窗口打开OA显示工具栏,3-在新窗口打开)',
  `LAST_PASS_TIME` datetime NOT NULL DEFAULT '0000-00-00 00:00:00' COMMENT '上次修改密码的时间',
  `THEME` tinyint(3) unsigned NOT NULL DEFAULT '10' COMMENT '界面主题',
  `SHORTCUT` varchar(100) NOT NULL DEFAULT '' COMMENT '快捷菜单ID串',
  `PORTAL` varchar(20) NOT NULL DEFAULT '' COMMENT '门户ID串',
  `PANEL` char(1) NOT NULL DEFAULT '1' COMMENT '登录后显示的左侧面板(1-导航,2-组织,3-短信,4-搜索)',
  `ONLINE` int(11) NOT NULL DEFAULT '0' COMMENT '在线时长',
  `ON_STATUS` char(1) NOT NULL DEFAULT '1' COMMENT '记录在线状态(1-联机,2-忙碌,3-离开)',
  `ATTEND_STATUS` char(1) NOT NULL DEFAULT '0' COMMENT '岗位状态(1-出差,2-请假,3-外出)',
  `MOBIL_NO_HIDDEN` char(1) NOT NULL DEFAULT '0' COMMENT '手机号码是否公开(0-公开,1-不公开)',
  `MYTABLE_LEFT` varchar(200) NOT NULL DEFAULT 'ALL' COMMENT '左侧的桌面模块',
  `MYTABLE_RIGHT` varchar(200) NOT NULL DEFAULT 'ALL' COMMENT '右侧的桌面模块',
  `USER_PRIV_OTHER` varchar(100) CHARACTER SET keybcs2 NOT NULL DEFAULT '' COMMENT '辅助角色编码串',
  `USER_NO` smallint(5) unsigned NOT NULL DEFAULT '10' COMMENT '用户排序号',
  `NOT_LOGIN` char(1) NOT NULL DEFAULT '0' COMMENT '禁止登录OA系统(1-禁止,0-不禁止)',
  `NOT_VIEW_USER` char(1) NOT NULL DEFAULT '0' COMMENT '禁止查看用户列表(1-禁止,0-不禁止)',
  `NOT_VIEW_TABLE` char(1) NOT NULL DEFAULT '0' COMMENT '禁止显示桌面(1-禁止,0-不禁止)',
  `NOT_SEARCH` char(1) NOT NULL DEFAULT '0' COMMENT '禁止OA搜索(1-禁止,0-不禁止)',
  `BKGROUND` varchar(200) NOT NULL DEFAULT '' COMMENT '桌面背景图片',
  `BIND_IP` varchar(200) NOT NULL DEFAULT '' COMMENT '绑定IP地址',
  `LAST_VISIT_IP` varchar(20) NOT NULL DEFAULT '' COMMENT '上次访问系统的IP',
  `MENU_IMAGE` varchar(10) NOT NULL DEFAULT '0' COMMENT '菜单图标(0-每个菜单使用不同图标,1-不显示菜单图标)',
  `WEATHER_CITY` varchar(50) DEFAULT NULL,
  `SHOW_RSS` char(1) NOT NULL DEFAULT '1' COMMENT '是否显示今日资讯(1-显示,0-不显示)',
  `MY_RSS` text NOT NULL COMMENT '今日资讯中的网址设置',
  `REMARK` text NOT NULL COMMENT '备注',
  `MENU_EXPAND` char(2) NOT NULL DEFAULT '' COMMENT '默认展开菜单',
  `MY_STATUS` varchar(200) NOT NULL DEFAULT '' COMMENT '个性签名',
  `LIMIT_LOGIN` char(1) NOT NULL DEFAULT '0' COMMENT '登录次数限制',
  `PHOTO` varchar(20) NOT NULL COMMENT '用户名片图片',
  `IM_RANGE` tinyint(3) unsigned NOT NULL DEFAULT '1' COMMENT '即时通讯使用权限(1-允许使用,2-禁止使用)',
  `LEAVE_TIME` datetime NOT NULL COMMENT '早退时间',
  `SECRET_LEVEL` int(2) DEFAULT '0' COMMENT '邮件密级类型(1-非涉密,2-秘密[一般],3-机密[重要],4-绝密[非常重要])',
  `USER_PARA` text NOT NULL COMMENT '用户参数',
  `NOT_MOBILE_LOGIN` char(1) NOT NULL DEFAULT '0' COMMENT '禁止登录OA系统手机客户端(1-禁止,0-不禁止)',
  `USER_byID` varchar(20) DEFAULT NULL,
  `USER_JOB` varchar(20) DEFAULT NULL,
  `USER_BU` varchar(30) DEFAULT '' COMMENT '组织归属: 1银河表计；2银河电网；3银河耐吉；4慧联通信；6集团',
  `IS_KH` varchar(1) DEFAULT NULL,
  `REAL_NAME` varchar(60) DEFAULT NULL,
  `JM_NAME` varchar(60) DEFAULT NULL,
  PRIMARY KEY (`UID`),
  UNIQUE KEY `USER_ID` (`USER_ID`),
  KEY `USER_PRIV` (`USER_PRIV`),
  KEY `DEPT_ID` (`DEPT_ID`),
  KEY `BYNAME` (`BYNAME`),
  KEY `PRIV_NO_NAME` (`USER_PRIV_NO`,`USER_NO`,`USER_NAME`),
  KEY `USER_NAME_INDEX` (`USER_NAME_INDEX`),
  KEY `USER_PRIV_OTHER` (`USER_PRIV_OTHER`)
) ENGINE=InnoDB AUTO_INCREMENT=20019 DEFAULT CHARSET=gbk COMMENT='用户表';

